def _get_style(self) -> dict:
    """Get the style for the component.

    Returns:
        The dictionary of the component style as value and the style notation as key.
    """
    if isinstance(self.style, Var):
        return {"css": self.style}
    emotion_style = format_as_emotion(self.style)
    return (
        {"css": LiteralVar.create(emotion_style)}
        if emotion_style is not None
        else {}
    )

def render(self) -> dict:
    """Render the component.

    Returns:
        The dictionary for template of component.
    """
    tag = self._render()
    rendered_dict = dict(
        tag.set(
            children=[child.render() for child in self.children],
            contents=str(tag.contents),
            props=tag.format_props(),
        ),
        autofocus=self.autofocus,
    )
    self._replace_prop_names(rendered_dict)
    return rendered_dict

def _replace_prop_names(self, rendered_dict: dict) -> None:
    """Replace the prop names in the render dictionary.

    Args:
        rendered_dict: The render dictionary with all the component props and event handlers.
    """
    # fast path
    if not self._rename_props:
        return

    for ix, prop in enumerate(rendered_dict["props"]):
        for old_prop, new_prop in self._rename_props.items():
            if prop.startswith(old_prop):
                rendered_dict["props"][ix] = prop.replace(old_prop, new_prop, 1)

def _validate_component_children(self, children: list[Component]):
    """Validate the children components.

    Args:
        children: The children of the component.

    """
    from reflex.components.base.fragment import Fragment
    from reflex.components.core.cond import Cond
    from reflex.components.core.foreach import Foreach
    from reflex.components.core.match import Match

    no_valid_parents_defined = all(child._valid_parents == [] for child in children)
    if (
        not self._invalid_children
        and not self._valid_children
        and no_valid_parents_defined
    ):
        return

    comp_name = type(self).__name__
    allowed_components = [
        comp.__name__ for comp in (Fragment, Foreach, Cond, Match)
    ]

    def validate_child(child: Any):
        child_name = type(child).__name__

        # Iterate through the immediate children of fragment
        if isinstance(child, Fragment):
            for c in child.children:
                validate_child(c)

        ):
            args = get_args(event_spec_return_type)

            args_types_without_vars = [
                arg if get_origin(arg) is not Var else get_args(arg)[0] for arg in args
            ]

            # check that args of event handler are matching the spec if type hints are provided
            for i, arg in enumerate(
                event_callback_spec_args[1 : len(args_types_without_vars) + 1]
            ):
                if arg not in type_hints_of_provided_callback:
                    continue

                type_match_found.setdefault(arg, False)

                try:
                    compare_result = typehint_issubclass(
                        args_types_without_vars[i], type_hints_of_provided_callback[arg]
                    )
                except TypeError as te:
                    raise TypeError(
                        f"Could not compare types {args_types_without_vars[i]} and {type_hints_of_provided_callback[arg]} for argument {arg} of {event_callback.fn.__qualname__} provided for {key}."
                    ) from te

                if compare_result:
                    type_match_found[arg] = True
                    continue
                else:
                    type_match_found[arg] = False
                    delayed_exceptions.append(
                        EventHandlerArgTypeMismatchError(
                            f"Event handler {key} expects {args_types_without_vars[i]} for argument {arg} but got {type_hints_of_provided_callback[arg]} as annotated in {event_callback.fn.__qualname__} instead."
                        )
                    )

            if all(type_match_found.values()):
                delayed_exceptions.clear()
                if event_spec_index:
                    args = get_args(event_spec_return_types[0])

                    args_types_without_vars = [
                        arg if get_origin(arg) is not Var else get_args(arg)[0]
                        for arg in args
                    ]

                    expect_string = ", ".join(
                        repr(arg) for arg in args_types_without_vars
                    ).replace("[", "\\[")

                    given_string = ", ".join(
                        repr(type_hints_of_provided_callback.get(arg, Any))
                        for arg in event_callback_spec_args[1:]
                    ).replace("[", "\\[")

                    console.warn(
                        f"Event handler {key} expects ({expect_string}) -> () but got ({given_string}) -> () as annotated in {event_callback.fn.__qualname__} instead. "
                        f"This may lead to unexpected behavior but is intentionally ignored for {key}."
                    )
                break

    if delayed_exceptions:
        raise delayed_exceptions[0]

    return event_callback(*event_spec_args)


def unwrap_var_annotation(annotation: GenericType):
    """Unwrap a Var annotation or return it as is if it's not Var[X].

    Args:
        annotation: The annotation to unwrap.

    Returns:
        The unwrapped annotation.
    """
    if get_origin(annotation) in (Var, ObjectVar) and (args := get_args(annotation)):
        return args[0]
    return annotation


def resolve_annotation(annotations: dict[str, Any], arg_name: str, spec: ArgsSpec):
    """Resolve the annotation for the given argument name.

    Args:
        annotations: The annotations.
        arg_name: The argument name.
        spec: The specs which the annotations come from.

    Raises:
        MissingAnnotationError: If the annotation is missing for non-lambda methods.

    """
    if types.is_union(cls):
        return all(can_use_in_object_var(t) for t in types.get_args(cls))
    return (
        inspect.isclass(cls)
        and not safe_issubclass(cls, Var)
        and serializers.can_serialize(cls, dict)
    )


